import yaml
import json

with open('data/2111.01152/2111.01152.yaml', 'r') as f:
    data = yaml.safe_load(f)

tasks = [item for item in data if 'task' in item]

# Extract placeholder-level scores per evaluator
all_placeholder_scores = []
for i, task in enumerate(tasks):
    placeholder = task.get('placeholder', {})
    task_name = task.get('task', 'N/A')
    for field_name, field_data in placeholder.items():
        if isinstance(field_data, dict) and 'score' in field_data:
            score_dict = field_data['score']
            for evaluator, score_val in score_dict.items():
                if evaluator.startswith('#'):
                    continue
                if isinstance(score_val, (int, float)):
                    all_placeholder_scores.append({
                        'task_idx': i,
                        'task_name': task_name,
                        'field': field_name,
                        'evaluator': evaluator,
                        'score': score_val
                    })

# Summary statistics
print(f'Total placeholder-level scores: {len(all_placeholder_scores)}')
evaluators = set(s['evaluator'] for s in all_placeholder_scores)
print(f'Evaluators: {evaluators}')

# Per-task summary
for i, task in enumerate(tasks):
    task_name = task.get('task', 'N/A')
    placeholder = task.get('placeholder', {})
    total_fields = 0
    scored_fields = 0
    avg_scores_by_eval = {}
    for field_name, field_data in placeholder.items():
        if isinstance(field_data, dict) and 'score' in field_data:
            scored_fields += 1
            score_dict = field_data['score']
            for ev, val in score_dict.items():
                if not ev.startswith('#') and isinstance(val, (int, float)):
                    avg_scores_by_eval.setdefault(ev, []).append(val)
        elif isinstance(field_data, dict):
            total_fields += 1
    total_fields += scored_fields

    # Task-level score
    task_score = task.get('score', {})
    task_score_vals = {}
    for k, v in task_score.items():
        if not k.startswith('#') and isinstance(v, (int, float)):
            task_score_vals[k] = v

    avg_task_score = sum(task_score_vals.values()) / len(task_score_vals) if task_score_vals else 0
    print(f'Task {i}: {task_name[:50]}')
    print(f'  Task-level avg score: {avg_task_score:.2f} / 2.0')
    print(f'  Scored placeholder fields: {scored_fields}')
